// Normaliza os dados recebidos do Webhook da Landing Page
const item = $input.first().json;
let data = item.body !== undefined ? item.body : item;

// Se o body veio como String/Texto (ex: enviado pelo navegador via fetch),
// fazemos o JSON.parse para extrair todos os campos corretamente!
if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch (e) {
    data = {};
  }
}
if (data && typeof data.body === 'string') {
  try {
    data = JSON.parse(data.body);
  } catch (e) {}
}

const nome = data.nome || 'Cliente';
const whatsapp = data.whatsapp || 'Não informado';
const cpf = data.cpf || 'Não informado';
const fipe = data.fipe_faixa || 'Até R$ 50 mil';
const reboque = data.reboque || 'Reboque 100 km';
const total = data.valor_total_formatado || `R$ ${parseFloat(data.valor_total || 0).toFixed(2).replace('.', ',')}/mês`;
const dataHora = data.data_hora || new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

// Limpeza de telefone para link direto do WhatsApp
const cleanDigits = (whatsapp || '').replace(/\D/g, '');
const intlPhone = cleanDigits.length === 10 || cleanDigits.length === 11 ? '55' + cleanDigits : cleanDigits;
const waLink = data.whatsapp_link || `https://wa.me/${intlPhone}`;

// Lista formatada de coberturas extras
let opcionaisTexto = '';
if (Array.isArray(data.opcionais) && data.opcionais.length > 0) {
  opcionaisTexto = data.opcionais.map(o => `• ${o.title} (+R$ ${parseFloat(o.price || 0).toFixed(2).replace('.', ',')}/mês)`).join('\n');
} else if (data.opcionais_texto) {
  opcionaisTexto = data.opcionais_texto;
} else {
  opcionaisTexto = '• Apenas Plano Essencial (Sem adicionais)';
}

// 1. Mensagem estruturada para o TELEGRAM
const telegramMsg = `🚗 <b>NOVA COTAÇÃO RECEBIDA - VALORIZA CAR</b>\n\n` +
  `👤 <b>Cliente:</b> ${nome}\n` +
  `📄 <b>CPF:</b> ${cpf}\n` +
  `📱 <b>WhatsApp:</b> ${whatsapp}\n` +
  `🚘 <b>Faixa FIPE:</b> ${fipe}\n` +
  `🚛 <b>Guincho / Reboque:</b> ${reboque}\n` +
  `✨ <b>Coberturas Extras:</b>\n${opcionaisTexto}\n\n` +
  `💰 <b>Valor Estimado:</b> <b>${total}</b>\n` +
  `📅 <b>Data/Hora:</b> ${dataHora}\n\n` +
  `👉 <a href="${waLink}"><b>CLIQUE AQUI PARA FALAR COM O CLIENTE NO WHATSAPP</b></a>`;

// 2. Assunto e Corpo HTML estruturado para o GMAIL
const emailSubject = `🚗 Nova Cotação Valoriza Car: ${nome} - ${total}`;

const emailHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8" />
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f7f9fc; margin: 0; padding: 24px;">
  <div style="max-width: 600px; margin: 0 auto; background-color: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.06); border: 1px solid #e2e8f0;">
    <div style="background-color: #0095D9; padding: 28px 24px; text-align: center; color: #ffffff;">
      <h1 style="margin: 0; font-size: 22px; font-weight: 800; letter-spacing: -0.5px;">VALORIZA CAR</h1>
      <p style="margin: 6px 0 0 0; font-size: 13px; opacity: 0.95; font-weight: 500;">Nova Cotação de Proteção Veicular Recebida</p>
    </div>
    <div style="padding: 24px 28px; color: #1c1c1c;">
      <p style="font-size: 14px; margin-top: 0; color: #54595f;">
        Um visitante acaba de montar um plano personalizado na landing page. Veja os detalhes abaixo:
      </p>

      <div style="background-color: #f8fafc; border-radius: 12px; padding: 18px; margin: 18px 0; border: 1px solid #e2e8f0;">
        <table style="width: 100%; border-collapse: collapse; font-size: 13px;">
          <tr>
            <td style="padding: 6px 0; color: #7a7a7a; width: 110px;"><strong>Nome:</strong></td>
            <td style="padding: 6px 0; font-weight: bold; color: #1c1c1c;">${nome}</td>
          </tr>
          <tr>
            <td style="padding: 6px 0; color: #7a7a7a;"><strong>CPF:</strong></td>
            <td style="padding: 6px 0; font-weight: 600; color: #1c1c1c;">${cpf}</td>
          </tr>
          <tr>
            <td style="padding: 6px 0; color: #7a7a7a;"><strong>WhatsApp:</strong></td>
            <td style="padding: 6px 0;"><a href="${waLink}" style="color: #0095D9; text-decoration: none; font-weight: bold;">${whatsapp}</a></td>
          </tr>
          <tr>
            <td style="padding: 6px 0; color: #7a7a7a;"><strong>Data/Hora:</strong></td>
            <td style="padding: 6px 0; color: #54595f;">${dataHora}</td>
          </tr>
        </table>
      </div>

      <h3 style="font-size: 14px; text-transform: uppercase; letter-spacing: 0.5px; color: #0095D9; margin: 20px 0 10px 0; border-bottom: 2px solid #f1f5f9; padding-bottom: 6px;">
        Resumo da Proteção Escolhida
      </h3>
      <ul style="padding-left: 18px; margin: 0; font-size: 13px; line-height: 1.8; color: #334155;">
        <li><strong>Plano Base:</strong> Essencial (Roubo, Furto, Colisão, Natureza e 24h)</li>
        <li><strong>Faixa FIPE:</strong> ${fipe}</li>
        <li><strong>Reboque:</strong> ${reboque}</li>
      </ul>

      <div style="margin-top: 12px; background-color: #f1f5f9; padding: 12px 16px; border-radius: 10px; font-size: 12px; color: #334155;">
        <strong>Opcionais Ativados:</strong><br />
        <pre style="margin: 6px 0 0 0; font-family: inherit; white-space: pre-wrap;">${opcionaisTexto}</pre>
      </div>

      <div style="background-color: #1b252f; color: #ffffff; padding: 18px; border-radius: 12px; text-align: center; margin-top: 22px;">
        <span style="font-size: 11px; text-transform: uppercase; color: #feca0a; font-weight: bold; letter-spacing: 1px;">Valor Total Estimado</span>
        <div style="font-size: 28px; font-weight: 800; margin-top: 4px; color: #ffffff;">${total}</div>
      </div>

      <div style="text-align: center; margin-top: 24px;">
        <a href="${waLink}" style="background-color: #23a455; color: #ffffff; padding: 14px 28px; text-decoration: none; border-radius: 12px; font-weight: bold; font-size: 14px; display: inline-block; box-shadow: 0 4px 12px rgba(35, 164, 85, 0.3);">
          Conversar com ${nome} no WhatsApp
        </a>
      </div>
    </div>
    <div style="background-color: #f8fafc; padding: 14px; text-align: center; font-size: 11px; color: #94a3b8; border-top: 1px solid #e2e8f0;">
      Valoriza Car Proteção Veicular • Notificação Automática N8N
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    nome,
    whatsapp,
    cpf,
    fipe,
    reboque,
    total,
    dataHora,
    waLink,
    telegramMsg,
    emailSubject,
    emailHtml
  }
}];
